    public static let json: String = "{\"$comment\":\"secuTG 加密使用指南唯一内容源（PLAN.md 3.15）。章节 / 步骤 / 配图场景五端一致；生成脚本 tools/gen-secutg-guide.py 产出各端表。scene.items 由各端的手机屏渲染器绘制。\",\"languages\":[\"en\",\"zh-Hans\",\"zh-Hant\"],\"chapters\":[{\"id\":\"private\",\"icon\":\"🔒\",\"title\":{\"en\":\"Encrypting a private chat\",\"zh-Hans\":\"私聊怎么用加密\",\"zh-Hant\":\"私聊怎麼用加密\"},\"summary\":{\"en\":\"Two people, about 30 seconds. Only text is encrypted — photos, voice and files still travel the ordinary Telegram way.\",\"zh-Hans\":\"两个人第一次加密聊天，全程约 30 秒。只加密文字，图片、语音、文件仍按 Telegram 原样发送。\",\"zh-Hant\":\"兩個人第一次加密聊天，全程約 30 秒。只加密文字，圖片、語音、檔案仍按 Telegram 原樣傳送。\"},\"steps\":[{\"id\":\"private.lock\",\"title\":{\"en\":\"Tap the lock button\",\"zh-Hans\":\"点右上角的锁按钮\",\"zh-Hant\":\"點右上角的鎖按鈕\"},\"body\":{\"en\":\"Green means this chat already has a key, grey means it has none. Tapping it opens the Si4Gram menu.\",\"zh-Hans\":\"绿色表示这个聊天已经有钥匙，灰色表示还没有。点开就是 Si4Gram 菜单。\",\"zh-Hant\":\"綠色表示這個聊天已經有鑰匙，灰色表示還沒有。點開就是 Si4Gram 選單。\"},\"anchor\":\"lockButton\",\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Alex\",\"zh-Hans\":\"小明\",\"zh-Hant\":\"小明\"},\"subtitle\":{\"en\":\"last seen recently\",\"zh-Hans\":\"最近曾上线\",\"zh-Hant\":\"最近曾上線\"},\"lock\":\"off\",\"sheet\":\"none\",\"items\":[{\"k\":\"in\",\"t\":{\"en\":\"See you tomorrow\",\"zh-Hans\":\"明天见\",\"zh-Hant\":\"明天見\"}},{\"k\":\"out\",\"t\":{\"en\":\"Sure, what time?\",\"zh-Hans\":\"好，几点？\",\"zh-Hant\":\"好，幾點？\"}},{\"k\":\"in\",\"t\":{\"en\":\"Nine, the usual place\",\"zh-Hans\":\"九点，老地方\",\"zh-Hant\":\"九點，老地方\"}},{\"k\":\"input\"}]}},{\"id\":\"private.auto\",\"title\":{\"en\":\"Choose Auto-pair\",\"zh-Hans\":\"选「自动配对」\",\"zh-Hant\":\"選「自動配對」\"},\"body\":{\"en\":\"The app posts one public-key message into the chat and the other side receives an invitation. For a higher level, pick Pair manually and scan a QR code face to face.\",\"zh-Hans\":\"软件往聊天里发一条公钥消息，对方那边就会收到邀请。要更高等级就选「手动配对」，当面扫二维码。\",\"zh-Hant\":\"軟體往聊天裡發一條公鑰訊息，對方那邊就會收到邀請。要更高等級就選「手動配對」，當面掃二維碼。\"},\"anchor\":\"menuPair\",\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Alex\",\"zh-Hans\":\"小明\",\"zh-Hant\":\"小明\"},\"lock\":\"off\",\"sheet\":\"sheet\",\"items\":[{\"k\":\"item\",\"t\":{\"en\":\"Si4Gram end-to-end encryption\",\"zh-Hans\":\"Si4Gram 端到端加密\",\"zh-Hant\":\"Si4Gram 端對端加密\"},\"style\":\"caption\"},{\"k\":\"item\",\"t\":{\"en\":\"Auto-pair (invite them)\",\"zh-Hans\":\"自动配对（邀请对方）\",\"zh-Hant\":\"自動配對（邀請對方）\"},\"style\":\"hl\"},{\"k\":\"item\",\"t\":{\"en\":\"Pair manually…\",\"zh-Hans\":\"手动配对…\",\"zh-Hant\":\"手動配對…\"}},{\"k\":\"item\",\"t\":{\"en\":\"More…\",\"zh-Hans\":\"更多…\",\"zh-Hant\":\"更多…\"}},{\"k\":\"button\",\"t\":{\"en\":\"Cancel\",\"zh-Hans\":\"取消\",\"zh-Hant\":\"取消\"}}]}},{\"id\":\"private.accept\",\"title\":{\"en\":\"They tap Accept\",\"zh-Hans\":\"对方点「接受」\",\"zh-Hant\":\"對方點「接受」\"},\"body\":{\"en\":\"Tapping Not now is fine too — the invitation card stays in the chat and can be accepted at any time.\",\"zh-Hans\":\"点「暂不」也没关系，聊天里的邀请卡片一直有效，随时能再点。\",\"zh-Hant\":\"點「暫不」也沒關係，聊天裡的邀請卡片一直有效，隨時能再點。\"},\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Alex\",\"zh-Hans\":\"小明\",\"zh-Hant\":\"小明\"},\"lock\":\"off\",\"sheet\":\"dialog\",\"items\":[{\"k\":\"body\",\"t\":{\"en\":\"Alex invites you to start an encrypted conversation\",\"zh-Hans\":\"小明 邀请你开始加密对话\",\"zh-Hant\":\"小明 邀請你開始加密對話\"},\"style\":\"strong\"},{\"k\":\"body\",\"t\":{\"en\":\"After you accept, messages are encrypted on the device and the Telegram server only sees ciphertext.\",\"zh-Hans\":\"接受后，双方消息将在设备上加密，Telegram 服务器只能看到密文。\",\"zh-Hant\":\"接受後，雙方訊息將在裝置上加密，Telegram 伺服器只能看到密文。\"}},{\"k\":\"body\",\"t\":{\"en\":\"If your account is signed in on several devices, only the first device to accept completes the pairing. The others import the key afterwards.\",\"zh-Hans\":\"如果你的账号登录在多台设备上，只有第一台点「接受」的设备会完成配对，其它设备之后需要导入密钥。\",\"zh-Hant\":\"如果你的帳號登入在多台裝置上，只有第一台點「接受」的裝置會完成配對，其它裝置之後需要匯入金鑰。\"}},{\"k\":\"button\",\"t\":{\"en\":\"Accept\",\"zh-Hans\":\"接受\",\"zh-Hant\":\"接受\"},\"style\":\"primary\"},{\"k\":\"button\",\"t\":{\"en\":\"Not now\",\"zh-Hans\":\"暂不\",\"zh-Hant\":\"暫不\"}}]}},{\"id\":\"private.safety\",\"title\":{\"en\":\"Check the safety code somewhere else\",\"zh-Hans\":\"换个渠道核对安全码\",\"zh-Hant\":\"換個管道核對安全碼\"},\"body\":{\"en\":\"Both sides must see the same digits. Never send the code inside this chat — if someone really did swap the keys, they could rewrite the code along with it.\",\"zh-Hans\":\"两边数字必须一样。不能在这个聊天里发安全码：中间真有人换了密钥的话，他能把你发的码一起改掉。\",\"zh-Hant\":\"兩邊數字必須一樣。不能在這個聊天裡發安全碼：中間真有人換了金鑰的話，他能把你發的碼一起改掉。\"},\"anchor\":\"menuSafetyCode\",\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Alex\",\"zh-Hans\":\"小明\",\"zh-Hant\":\"小明\"},\"lock\":\"on\",\"sheet\":\"dialog\",\"items\":[{\"k\":\"body\",\"t\":{\"en\":\"Paired — this conversation is encrypted\",\"zh-Hans\":\"配对完成，本对话已加密\",\"zh-Hant\":\"配對完成，本對話已加密\"},\"style\":\"strong\"},{\"k\":\"code\",\"t\":{\"en\":\"4145 8544 3189\",\"zh-Hans\":\"4145 8544 3189\",\"zh-Hant\":\"4145 8544 3189\"}},{\"k\":\"body\",\"t\":{\"en\":\"To make sure nobody in the middle replaced the keys, compare these 12 digits with the other person through a channel outside this app — a phone call, or in person.\",\"zh-Hans\":\"为了防止中间渠道替换密钥，请通过此软件之外的渠道（电话、当面）与对方核对这 12 位数字。\",\"zh-Hant\":\"為了防止中間管道替換金鑰，請透過此軟體之外的管道（電話、當面）與對方核對這 12 位數字。\"}},{\"k\":\"button\",\"t\":{\"en\":\"They match\",\"zh-Hans\":\"一致，已核对\",\"zh-Hant\":\"一致，已核對\"},\"style\":\"primary\"},{\"k\":\"button\",\"t\":{\"en\":\"Check later\",\"zh-Hans\":\"稍后再核对\",\"zh-Hant\":\"稍後再核對\"}},{\"k\":\"button\",\"t\":{\"en\":\"They do not match…\",\"zh-Hans\":\"不一致…\",\"zh-Hant\":\"不一致…\"},\"style\":\"danger\"}]}},{\"id\":\"private.chat\",\"title\":{\"en\":\"Now the chat is encrypted\",\"zh-Hans\":\"开始加密聊天\",\"zh-Hant\":\"開始加密聊天\"},\"body\":{\"en\":\"Everything you send and every encrypted message you receive carries a lock. Plain text sent from an official build is marked, so the two are never confused.\",\"zh-Hans\":\"自己发的和收到的加密消息后面都带锁图标。对方用官方版发来的明文会被标出来，一眼能分辨。\",\"zh-Hant\":\"自己發的和收到的加密訊息後面都帶鎖圖示。對方用官方版發來的明文會被標出來，一眼能分辨。\"},\"anchor\":\"composerInput\",\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Alex\",\"zh-Hans\":\"小明\",\"zh-Hant\":\"小明\"},\"subtitle\":{\"en\":\"last seen recently\",\"zh-Hans\":\"最近曾上线\",\"zh-Hant\":\"最近曾上線\"},\"lock\":\"on\",\"sheet\":\"none\",\"items\":[{\"k\":\"service\",\"t\":{\"en\":\"🔐 Paired — messages in this chat are encrypted\",\"zh-Hans\":\"🔐 已配对，本聊天消息已加密\",\"zh-Hant\":\"🔐 已配對，本聊天訊息已加密\"}},{\"k\":\"out\",\"t\":{\"en\":\"Nine tomorrow then 🔒\",\"zh-Hans\":\"明天九点见 🔒\",\"zh-Hant\":\"明天九點見 🔒\"}},{\"k\":\"in\",\"t\":{\"en\":\"Got it  ⚠️ not encrypted\",\"zh-Hans\":\"收到  ⚠️ 此消息未加密\",\"zh-Hant\":\"收到  ⚠️ 此訊息未加密\"},\"style\":\"warn\"},{\"k\":\"out\",\"t\":{\"en\":\"You are on the official build, right? 🔒\",\"zh-Hans\":\"你装的是官方版吧 🔒\",\"zh-Hant\":\"你裝的是官方版吧 🔒\"}},{\"k\":\"input\"}]}},{\"id\":\"private.more\",\"title\":{\"en\":\"What else is under More\",\"zh-Hans\":\"「更多…」里还有什么\",\"zh-Hant\":\"「更多…」裡還有什麼\"},\"body\":{\"en\":\"After seven days the lock button turns into a warning and asks for a new key. If you suspect this device's key leaked, use Regenerate keys and pair again.\",\"zh-Hans\":\"密钥用满 7 天，锁按钮变成提醒图标，提示你换新密钥。怀疑本机密钥泄露就用「重新生成密钥并重新配对」。\",\"zh-Hant\":\"金鑰用滿 7 天，鎖按鈕變成提醒圖示，提示你換新金鑰。懷疑本機金鑰外洩就用「重新產生金鑰並重新配對」。\"},\"anchor\":\"menuMore\",\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Alex\",\"zh-Hans\":\"小明\",\"zh-Hant\":\"小明\"},\"lock\":\"on\",\"sheet\":\"sheet\",\"items\":[{\"k\":\"item\",\"t\":{\"en\":\"More…\",\"zh-Hans\":\"更多…\",\"zh-Hant\":\"更多…\"},\"style\":\"caption\"},{\"k\":\"item\",\"t\":{\"en\":\"New key\",\"zh-Hans\":\"换新密钥\",\"zh-Hant\":\"換新金鑰\"}},{\"k\":\"item\",\"t\":{\"en\":\"Forward secrecy: off (daily key)…\",\"zh-Hans\":\"前向保密：关（每天换钥）…\",\"zh-Hant\":\"前向保密：關（每天換鑰）…\"}},{\"k\":\"item\",\"t\":{\"en\":\"Regenerate keys and pair again…\",\"zh-Hans\":\"重新生成密钥并重新配对…\",\"zh-Hant\":\"重新產生金鑰並重新配對…\"},\"style\":\"danger\"},{\"k\":\"item\",\"t\":{\"en\":\"Unpair\",\"zh-Hans\":\"解除配对\",\"zh-Hant\":\"解除配對\"},\"style\":\"danger\"},{\"k\":\"item\",\"t\":{\"en\":\"Move keys ›\",\"zh-Hans\":\"密钥搬运 ›\",\"zh-Hant\":\"金鑰搬運 ›\"}},{\"k\":\"item\",\"t\":{\"en\":\"Si4Gram status\",\"zh-Hans\":\"Si4Gram 状态\",\"zh-Hant\":\"Si4Gram 狀態\"}},{\"k\":\"item\",\"t\":{\"en\":\"Guide and sponsor\",\"zh-Hans\":\"使用指南 · 赞助\",\"zh-Hant\":\"使用指南 · 贊助\"}}]}}]},{\"id\":\"member\",\"icon\":\"👥\",\"title\":{\"en\":\"Joining an encrypted group\",\"zh-Hans\":\"群聊怎么用加密（成员）\",\"zh-Hant\":\"群聊怎麼用加密（成員）\"},\"summary\":{\"en\":\"Once you are in an encrypted group there is only one thing to do: get the group key. There are two routes, and the admin will tell you which one.\",\"zh-Hans\":\"被拉进加密群后只有一件事要做：拿到群钥匙。两条路，管理员会告诉你走哪条。\",\"zh-Hant\":\"被拉進加密群後只有一件事要做：拿到群鑰匙。兩條路，管理員會告訴你走哪條。\"},\"steps\":[{\"id\":\"member.invite\",\"title\":{\"en\":\"The admin sends an invitation in your private chat\",\"zh-Hans\":\"管理员在私聊里发来邀请\",\"zh-Hant\":\"管理員在私聊裡發來邀請\"},\"body\":{\"en\":\"The easiest route. It needs you and the admin to be paired first, as in chapter 1, so its security equals that private chat's — check the safety code before you use it.\",\"zh-Hans\":\"最省事的一条路。前提是你和管理员已经按第 1 章配好对，安全性等于那条私聊的等级，所以建议先核对安全码。\",\"zh-Hant\":\"最省事的一條路。前提是你和管理員已經按第 1 章配好對，安全性等於那條私聊的等級，所以建議先核對安全碼。\"},\"anchor\":\"inviteCard\",\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Alex (admin)\",\"zh-Hans\":\"小明（管理员）\",\"zh-Hant\":\"小明（管理員）\"},\"subtitle\":{\"en\":\"encrypted private chat\",\"zh-Hans\":\"加密私聊\",\"zh-Hant\":\"加密私聊\"},\"lock\":\"on\",\"sheet\":\"none\",\"items\":[{\"k\":\"body\",\"t\":{\"en\":\"🔐 Alex invites you to the encrypted group “Project team”\",\"zh-Hans\":\"🔐 小明 邀请你加入加密群「项目组」\",\"zh-Hant\":\"🔐 小明 邀請你加入加密群「專案組」\"},\"style\":\"strong\"},{\"k\":\"body\",\"t\":{\"en\":\"One tap imports the group key, registers your public key in the group, and turns on encryption from then on.\",\"zh-Hans\":\"点一下即可导入群密钥、在群里登记你的公钥，之后群消息自动加密解密。\",\"zh-Hant\":\"點一下即可匯入群金鑰、在群裡登記你的公鑰，之後群訊息自動加密解密。\"}},{\"k\":\"button\",\"t\":{\"en\":\"Import and join\",\"zh-Hans\":\"导入并加入\",\"zh-Hant\":\"匯入並加入\"},\"style\":\"primary\"},{\"k\":\"body\",\"t\":{\"en\":\"The whole card arrives encrypted, so the server never sees the key.\",\"zh-Hans\":\"整张卡片是加密发来的，服务器看不到钥匙。\",\"zh-Hant\":\"整張卡片是加密發來的，伺服器看不到鑰匙。\"}},{\"k\":\"input\"}]}},{\"id\":\"member.scan\",\"title\":{\"en\":\"Or scan the QR code in person\",\"zh-Hans\":\"或者当面扫二维码\",\"zh-Hant\":\"或者當面掃二維碼\"},\"body\":{\"en\":\"Scan the group key from the admin's screen. The key never touches the network, which is the offline security level.\",\"zh-Hans\":\"扫管理员屏幕上的群密钥二维码。钥匙完全不经过网络，安全等级「线下」。\",\"zh-Hant\":\"掃管理員螢幕上的群金鑰二維碼。鑰匙完全不經過網路，安全等級「線下」。\"},\"anchor\":\"menuImportKeyOffline\",\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Project team\",\"zh-Hans\":\"项目组\",\"zh-Hant\":\"專案組\"},\"subtitle\":{\"en\":\"8 members\",\"zh-Hans\":\"8 位成员\",\"zh-Hant\":\"8 位成員\"},\"lock\":\"off\",\"sheet\":\"sheet\",\"items\":[{\"k\":\"item\",\"t\":{\"en\":\"Si4Gram end-to-end encryption\",\"zh-Hans\":\"Si4Gram 端到端加密\",\"zh-Hant\":\"Si4Gram 端對端加密\"},\"style\":\"caption\"},{\"k\":\"item\",\"t\":{\"en\":\"Scan or paste the group key\",\"zh-Hans\":\"扫码 / 粘贴导入群密钥\",\"zh-Hant\":\"掃碼 / 貼上匯入群金鑰\"},\"style\":\"hl\"},{\"k\":\"item\",\"t\":{\"en\":\"More…\",\"zh-Hans\":\"更多…\",\"zh-Hant\":\"更多…\"}},{\"k\":\"button\",\"t\":{\"en\":\"Cancel\",\"zh-Hans\":\"取消\",\"zh-Hant\":\"取消\"}}]}},{\"id\":\"member.done\",\"title\":{\"en\":\"After that there is nothing to do\",\"zh-Hans\":\"之后就不用管了\",\"zh-Hant\":\"之後就不用管了\"},\"body\":{\"en\":\"Group messages encrypt and decrypt on their own. When the admin rotates the key, adds or removes someone, your device follows automatically.\",\"zh-Hans\":\"群消息自动加解密。管理员换钥、加人、踢人，你这边都自动跟上。\",\"zh-Hant\":\"群訊息自動加解密。管理員換鑰、加人、踢人，你這邊都自動跟上。\"},\"scene\":{\"chrome\":\"page\",\"title\":{\"en\":\"Project team\",\"zh-Hans\":\"项目组\",\"zh-Hant\":\"專案組\"},\"sheet\":\"none\",\"items\":[{\"k\":\"body\",\"t\":{\"en\":\"Si4Gram status\",\"zh-Hans\":\"Si4Gram 状态\",\"zh-Hant\":\"Si4Gram 狀態\"},\"style\":\"strong\"},{\"k\":\"row\",\"t\":{\"en\":\"Version\",\"zh-Hans\":\"版本\",\"zh-Hant\":\"版本\"},\"v\":{\"en\":\"0.0.7\",\"zh-Hans\":\"0.0.7\",\"zh-Hant\":\"0.0.7\"}},{\"k\":\"row\",\"t\":{\"en\":\"Encryption\",\"zh-Hans\":\"加密\",\"zh-Hant\":\"加密\"},\"v\":{\"en\":\"on\",\"zh-Hans\":\"开\",\"zh-Hant\":\"開\"}},{\"k\":\"row\",\"t\":{\"en\":\"Security level\",\"zh-Hans\":\"安全等级\",\"zh-Hant\":\"安全等級\"},\"v\":{\"en\":\"offline\",\"zh-Hans\":\"线下\",\"zh-Hant\":\"線下\"},\"style\":\"hl\"},{\"k\":\"row\",\"t\":{\"en\":\"Key age\",\"zh-Hans\":\"密钥已使用\",\"zh-Hant\":\"金鑰已使用\"},\"v\":{\"en\":\"3 days\",\"zh-Hans\":\"3 天\",\"zh-Hant\":\"3 天\"}},{\"k\":\"row\",\"t\":{\"en\":\"Role\",\"zh-Hans\":\"角色\",\"zh-Hant\":\"角色\"},\"v\":{\"en\":\"member\",\"zh-Hans\":\"成员\",\"zh-Hant\":\"成員\"}},{\"k\":\"row\",\"t\":{\"en\":\"Registered public keys\",\"zh-Hans\":\"已登记成员公钥\",\"zh-Hant\":\"已登記成員公鑰\"},\"v\":{\"en\":\"5\",\"zh-Hans\":\"5\",\"zh-Hant\":\"5\"}}]}}]},{\"id\":\"admin\",\"icon\":\"🔑\",\"title\":{\"en\":\"Running an encrypted group\",\"zh-Hans\":\"群管理员怎么用\",\"zh-Hant\":\"群管理員怎麼用\"},\"summary\":{\"en\":\"The device that created the key holds the only admin signing key — only it can rotate the key, add members and remove them. If that device is lost the group has to start over, so make a key-transfer backup first (chapter 4).\",\"zh-Hans\":\"建钥匙的那台设备持有唯一的管理员签名私钥，只有它能换钥、加人、踢人。这台设备丢了，群就得重建钥匙、所有人重来，所以务必先做一份密钥搬运备份（第 4 章）。\",\"zh-Hant\":\"建鑰匙的那台裝置持有唯一的管理員簽名私鑰，只有它能換鑰、加人、踢人。這台裝置丟了，群就得重建鑰匙、所有人重來，所以務必先做一份金鑰搬運備份（第 4 章）。\"},\"steps\":[{\"id\":\"admin.create\",\"title\":{\"en\":\"Create the group key\",\"zh-Hans\":\"建群钥匙\",\"zh-Hant\":\"建群鑰匙\"},\"body\":{\"en\":\"The device generates one group key and one admin signing key pair. Encryption turns on right away.\",\"zh-Hans\":\"本机生成一把群钥匙和一对管理员签名密钥，加密立即开启。\",\"zh-Hant\":\"本機產生一把群鑰匙和一對管理員簽名金鑰，加密立即開啟。\"},\"anchor\":\"menuSetupKey\",\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Project team\",\"zh-Hans\":\"项目组\",\"zh-Hant\":\"專案組\"},\"subtitle\":{\"en\":\"8 members\",\"zh-Hans\":\"8 位成员\",\"zh-Hant\":\"8 位成員\"},\"lock\":\"off\",\"sheet\":\"sheet\",\"items\":[{\"k\":\"item\",\"t\":{\"en\":\"Si4Gram end-to-end encryption\",\"zh-Hans\":\"Si4Gram 端到端加密\",\"zh-Hant\":\"Si4Gram 端對端加密\"},\"style\":\"caption\"},{\"k\":\"item\",\"t\":{\"en\":\"Create the group key (I am the admin)…\",\"zh-Hans\":\"创建群密钥（我是管理员）…\",\"zh-Hant\":\"建立群金鑰（我是管理員）…\"},\"style\":\"hl\"},{\"k\":\"item\",\"t\":{\"en\":\"Scan or paste the group key\",\"zh-Hans\":\"扫码 / 粘贴导入群密钥\",\"zh-Hant\":\"掃碼 / 貼上匯入群金鑰\"}},{\"k\":\"item\",\"t\":{\"en\":\"More…\",\"zh-Hans\":\"更多…\",\"zh-Hant\":\"更多…\"}},{\"k\":\"button\",\"t\":{\"en\":\"Cancel\",\"zh-Hans\":\"取消\",\"zh-Hant\":\"取消\"}}]}},{\"id\":\"admin.offline\",\"title\":{\"en\":\"Offline invitation (level: offline)\",\"zh-Hans\":\"线下邀请（等级：线下）\",\"zh-Hant\":\"線下邀請（等級：線下）\"},\"body\":{\"en\":\"The menu entry is Offline invitation — group key QR. It is the safest route, because the key never goes online.\",\"zh-Hans\":\"菜单里的「线下邀请 · 群密钥二维码」。最安全，钥匙完全不上网。\",\"zh-Hant\":\"選單裡的「線下邀請 · 群金鑰二維碼」。最安全，鑰匙完全不上網。\"},\"anchor\":\"menuInviteOffline\",\"scene\":{\"chrome\":\"page\",\"title\":{\"en\":\"Group key\",\"zh-Hans\":\"群密钥\",\"zh-Hant\":\"群金鑰\"},\"sheet\":\"none\",\"items\":[{\"k\":\"qr\"},{\"k\":\"body\",\"t\":{\"en\":\"Let members scan this from your screen\",\"zh-Hans\":\"让成员当面扫这张码\",\"zh-Hant\":\"讓成員當面掃這張碼\"}},{\"k\":\"body\",\"t\":{\"en\":\"Never send it through Telegram\",\"zh-Hans\":\"不要发进 Telegram\",\"zh-Hant\":\"不要傳進 Telegram\"},\"style\":\"danger\"},{\"k\":\"button\",\"t\":{\"en\":\"Copy key text\",\"zh-Hans\":\"复制密钥文本\",\"zh-Hant\":\"複製金鑰文字\"}}]}},{\"id\":\"admin.online\",\"title\":{\"en\":\"Online invitation (level: online)\",\"zh-Hans\":\"线上邀请（等级：线上）\",\"zh-Hant\":\"線上邀請（等級：線上）\"},\"body\":{\"en\":\"Members and keys → Online invitation. Each name shows the level of your private chat with that person. Anyone whose safety code is unchecked gets a prompt first.\",\"zh-Hans\":\"「成员与换钥… → 线上邀请」。每个人后面标着你和他那条私聊的等级，没核对安全码的会先提示你核对。\",\"zh-Hant\":\"「成員與換鑰… → 線上邀請」。每個人後面標著你和他那條私聊的等級，沒核對安全碼的會先提示你核對。\"},\"anchor\":\"menuInviteOnline\",\"scene\":{\"chrome\":\"page\",\"title\":{\"en\":\"Online invitation\",\"zh-Hans\":\"线上邀请\",\"zh-Hant\":\"線上邀請\"},\"sheet\":\"none\",\"items\":[{\"k\":\"body\",\"t\":{\"en\":\"The group key is sent inside your encrypted private chat with each person you pick.\",\"zh-Hans\":\"选择要邀请的成员，群密钥会放在你和他的加密私聊里发送。\",\"zh-Hant\":\"選擇要邀請的成員，群金鑰會放在你和他的加密私聊裡傳送。\"}},{\"k\":\"row\",\"t\":{\"en\":\"Li\",\"zh-Hans\":\"李四\",\"zh-Hant\":\"李四\"},\"v\":{\"en\":\"encrypted · code checked\",\"zh-Hans\":\"已加密 · 已核对\",\"zh-Hant\":\"已加密 · 已核對\"},\"style\":\"hl\"},{\"k\":\"row\",\"t\":{\"en\":\"Wang\",\"zh-Hans\":\"王五\",\"zh-Hant\":\"王五\"},\"v\":{\"en\":\"encrypted · code unchecked\",\"zh-Hans\":\"已加密 · 未核对\",\"zh-Hant\":\"已加密 · 未核對\"},\"style\":\"warn\"},{\"k\":\"row\",\"t\":{\"en\":\"Zhao\",\"zh-Hans\":\"赵六\",\"zh-Hant\":\"趙六\"},\"v\":{\"en\":\"not encrypted · pair first\",\"zh-Hans\":\"未加密 · 先配对\",\"zh-Hant\":\"未加密 · 先配對\"}}]}},{\"id\":\"admin.members\",\"title\":{\"en\":\"Everyday upkeep lives here\",\"zh-Hans\":\"日常维护都在这里\",\"zh-Hant\":\"日常維護都在這裡\"},\"body\":{\"en\":\"Members register their public key automatically once they import the key, so later invitations and rotations need no meeting. Welcome hands over the current key, so the new person can read the history it covers — rotate first if you would rather they could not. Remove and rotate gives the new key only to the people who stayed.\",\"zh-Hans\":\"成员导入钥匙后会自动登记公钥，所以之后加人、换钥都不用再见面。「欢迎新人」给的是当前钥匙，他能看到这把钥匙生效期间的历史，不想给就先换钥再欢迎。「踢人换钥」只把新钥匙发给留下的人。\",\"zh-Hant\":\"成員匯入鑰匙後會自動登記公鑰，所以之後加人、換鑰都不用再見面。「歡迎新人」給的是目前的鑰匙，他能看到這把鑰匙生效期間的歷史，不想給就先換鑰再歡迎。「踢人換鑰」只把新鑰匙發給留下的人。\"},\"anchor\":\"menuMembers\",\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Project team\",\"zh-Hans\":\"项目组\",\"zh-Hant\":\"專案組\"},\"lock\":\"on\",\"sheet\":\"sheet\",\"items\":[{\"k\":\"item\",\"t\":{\"en\":\"Members and keys…\",\"zh-Hans\":\"成员与换钥…\",\"zh-Hant\":\"成員與換鑰…\"},\"style\":\"caption\"},{\"k\":\"item\",\"t\":{\"en\":\"Online invitation · via encrypted private chat\",\"zh-Hans\":\"线上邀请 · 经加密私聊发送\",\"zh-Hant\":\"線上邀請 · 經加密私聊傳送\"}},{\"k\":\"item\",\"t\":{\"en\":\"Register a member public key…\",\"zh-Hans\":\"登记成员公钥…\",\"zh-Hant\":\"登記成員公鑰…\"}},{\"k\":\"item\",\"t\":{\"en\":\"Welcome a new member…\",\"zh-Hans\":\"欢迎新人…\",\"zh-Hant\":\"歡迎新人…\"}},{\"k\":\"item\",\"t\":{\"en\":\"Remove and rotate…\",\"zh-Hans\":\"踢人换钥…\",\"zh-Hant\":\"踢人換鑰…\"},\"style\":\"danger\"},{\"k\":\"item\",\"t\":{\"en\":\"New key\",\"zh-Hans\":\"换新密钥\",\"zh-Hant\":\"換新金鑰\"}}]}},{\"id\":\"admin.due\",\"title\":{\"en\":\"The key expiry reminder\",\"zh-Hans\":\"到期提醒\",\"zh-Hant\":\"到期提醒\"},\"body\":{\"en\":\"After seven days the lock button turns into a warning and the first menu row asks for a new key. Members see “ask the admin to rotate” instead, because they hold no signing key.\",\"zh-Hans\":\"群钥匙用满 7 天，锁按钮变成提醒图标，菜单第一行出现提醒，点一下就换。成员那边看到的是「请让管理员换钥」，因为他们没有签名私钥。\",\"zh-Hant\":\"群鑰匙用滿 7 天，鎖按鈕變成提醒圖示，選單第一行出現提醒，點一下就換。成員那邊看到的是「請讓管理員換鑰」，因為他們沒有簽名私鑰。\"},\"anchor\":\"statusKeyAge\",\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Project team\",\"zh-Hans\":\"项目组\",\"zh-Hant\":\"專案組\"},\"lock\":\"warn\",\"sheet\":\"sheet\",\"items\":[{\"k\":\"item\",\"t\":{\"en\":\"Si4Gram end-to-end encryption\",\"zh-Hans\":\"Si4Gram 端到端加密\",\"zh-Hant\":\"Si4Gram 端對端加密\"},\"style\":\"caption\"},{\"k\":\"item\",\"t\":{\"en\":\"⚠️ Key is 8 days old — time for a new one\",\"zh-Hans\":\"⚠️ 密钥已用 8 天，建议更换\",\"zh-Hant\":\"⚠️ 金鑰已用 8 天，建議更換\"},\"style\":\"warn\"},{\"k\":\"item\",\"t\":{\"en\":\"Encryption: on (tap to turn off)\",\"zh-Hans\":\"加密：开（点击关闭）\",\"zh-Hant\":\"加密：開（點擊關閉）\"}},{\"k\":\"item\",\"t\":{\"en\":\"Offline invitation · group key QR\",\"zh-Hans\":\"线下邀请 · 群密钥二维码\",\"zh-Hant\":\"線下邀請 · 群金鑰二維碼\"}},{\"k\":\"button\",\"t\":{\"en\":\"Cancel\",\"zh-Hans\":\"取消\",\"zh-Hant\":\"取消\"}}]}}]},{\"id\":\"other\",\"icon\":\"🧭\",\"title\":{\"en\":\"Other things worth knowing\",\"zh-Hans\":\"其他\",\"zh-Hant\":\"其他\"},\"summary\":{\"en\":\"Several devices, what the little icons mean, the security levels, and the few facts that come with a custom build.\",\"zh-Hans\":\"多设备、图标含义、安全等级，以及定制版要知道的几件事。\",\"zh-Hant\":\"多裝置、圖示含義、安全等級，以及自訂版要知道的幾件事。\"},\"steps\":[{\"id\":\"other.transfer\",\"title\":{\"en\":\"Several devices: moving the keys\",\"zh-Hans\":\"多设备：密钥搬运\",\"zh-Hant\":\"多裝置：金鑰搬運\"},\"body\":{\"en\":\"Keys live only on the device that made them. To let another device read and send too: export everything, move the file by AirDrop or Nearby Share, send the transfer code through a different channel, then import on the other device.\",\"zh-Hans\":\"钥匙只存在本机。要让另一台设备也能收发：导出全部 → 文件走隔空投送 / 就近分享，搬运码走另一条渠道 → 那台设备导入。\",\"zh-Hant\":\"鑰匙只存在本機。要讓另一台裝置也能收發：匯出全部 → 檔案走 AirDrop / 附近分享，搬運碼走另一條管道 → 那台裝置匯入。\"},\"anchor\":\"settingsTransfer\",\"scene\":{\"chrome\":\"page\",\"title\":{\"en\":\"Export keys\",\"zh-Hans\":\"导出密钥\",\"zh-Hant\":\"匯出金鑰\"},\"sheet\":\"none\",\"items\":[{\"k\":\"body\",\"t\":{\"en\":\"Everything · 12 chats · 27 keys\",\"zh-Hans\":\"全部密钥 · 12 个聊天 · 27 把钥匙\",\"zh-Hant\":\"全部金鑰 · 12 個聊天 · 27 把鑰匙\"}},{\"k\":\"body\",\"t\":{\"en\":\"Transfer code (shown this once only)\",\"zh-Hans\":\"搬运码（只显示这一次）\",\"zh-Hant\":\"搬運碼（只顯示這一次）\"}},{\"k\":\"code\",\"t\":{\"en\":\"4KJ8-2QM7-9XTB-R5NP\",\"zh-Hans\":\"4KJ8-2QM7-9XTB-R5NP\",\"zh-Hant\":\"4KJ8-2QM7-9XTB-R5NP\"}},{\"k\":\"body\",\"t\":{\"en\":\"This file plus the code is your whole encrypted identity. Send them through two different channels and delete both when done.\",\"zh-Hans\":\"这个文件加上搬运码等于你的全部加密身份，请分两条渠道传，用完即删。\",\"zh-Hant\":\"這個檔案加上搬運碼等於你的全部加密身分，請分兩條管道傳，用完即刪。\"},\"style\":\"danger\"},{\"k\":\"button\",\"t\":{\"en\":\"Share…\",\"zh-Hans\":\"分享…\",\"zh-Hant\":\"分享…\"},\"style\":\"primary\"},{\"k\":\"button\",\"t\":{\"en\":\"Save to file\",\"zh-Hans\":\"保存文件\",\"zh-Hant\":\"儲存檔案\"}}]}},{\"id\":\"other.icons\",\"title\":{\"en\":\"The small icons after a message\",\"zh-Hans\":\"消息后面的小图标\",\"zh-Hant\":\"訊息後面的小圖示\"},\"body\":{\"en\":\"🔒 encrypted, sent or received. A message this device has no key for says so in words instead of showing its ciphertext, and opens by itself once the key arrives. ⚠️ the chat is encrypted but that message came as plain text. 🔑 a key change, handled automatically. 🔐 pairing, key registration and group invitations.\",\"zh-Hans\":\"🔒 这条是加密的，自己发的和收到的都会标。本机没有钥匙的消息会直接说明原因，不再显示那串密文，等钥匙到了会自动变成正文。⚠️ 本聊天开了加密，但对方这条是明文发的。🔑 换钥消息，系统自动处理。🔐 配对、公钥登记、入群邀请一类的控制消息。\",\"zh-Hant\":\"🔒 這條是加密的，自己發的和收到的都會標。本機沒有鑰匙的訊息會直接說明原因，不再顯示那串密文，等鑰匙到了會自動變成正文。⚠️ 本聊天開了加密，但對方這條是明文發的。🔑 換鑰訊息，系統自動處理。🔐 配對、公鑰登記、入群邀請一類的控制訊息。\"},\"scene\":{\"chrome\":\"chat\",\"title\":{\"en\":\"Icons at a glance\",\"zh-Hans\":\"图标速查\",\"zh-Hant\":\"圖示速查\"},\"lock\":\"on\",\"sheet\":\"none\",\"items\":[{\"k\":\"out\",\"t\":{\"en\":\"An encrypted message 🔒\",\"zh-Hans\":\"已加密的消息 🔒\",\"zh-Hant\":\"已加密的訊息 🔒\"}},{\"k\":\"in\",\"t\":{\"en\":\"🔒 Encrypted message. This device has no key that opens it.\",\"zh-Hans\":\"🔒 已收到加密信息，本机没有可解密的密钥。\",\"zh-Hant\":\"🔒 已收到加密訊息，本機沒有可解密的金鑰。\"}},{\"k\":\"in\",\"t\":{\"en\":\"Are you there?  ⚠️ not encrypted\",\"zh-Hans\":\"在吗  ⚠️ 此消息未加密\",\"zh-Hant\":\"在嗎  ⚠️ 此訊息未加密\"},\"style\":\"warn\"},{\"k\":\"service\",\"t\":{\"en\":\"🔑 Key updated\",\"zh-Hans\":\"🔑 密钥已更新\",\"zh-Hant\":\"🔑 金鑰已更新\"}},{\"k\":\"service\",\"t\":{\"en\":\"🔐 Paired — messages in this chat are encrypted\",\"zh-Hans\":\"🔐 已配对，本聊天消息已加密\",\"zh-Hant\":\"🔐 已配對，本聊天訊息已加密\"}},{\"k\":\"input\"}]}},{\"id\":\"other.about\",\"title\":{\"en\":\"The About page\",\"zh-Hans\":\"关于页\",\"zh-Hant\":\"關於頁\"},\"body\":{\"en\":\"This build has every update check removed, so it never turns into the official app and never shows an update prompt. Upgrading means installing a new package yourself. Only download it from the official site and compare the version and build fingerprint printed there.\",\"zh-Hans\":\"这个版本已经关掉全部更新检查，不会变成官方版，也不会弹更新提示。要升级只能自己换安装包。请只从官网下载，并对照官网公布的版本号与构建指纹。\",\"zh-Hant\":\"這個版本已經關掉全部更新檢查，不會變成官方版，也不會彈更新提示。要升級只能自己換安裝包。請只從官網下載，並對照官網公布的版本號與建置指紋。\"},\"anchor\":\"settingsAbout\",\"scene\":{\"chrome\":\"page\",\"title\":{\"en\":\"About Si4Gram\",\"zh-Hans\":\"关于 Si4Gram\",\"zh-Hant\":\"關於 Si4Gram\"},\"sheet\":\"none\",\"items\":[{\"k\":\"row\",\"t\":{\"en\":\"Version\",\"zh-Hans\":\"版本\",\"zh-Hant\":\"版本\"},\"v\":{\"en\":\"0.0.7\",\"zh-Hans\":\"0.0.7\",\"zh-Hant\":\"0.0.7\"},\"style\":\"hl\"},{\"k\":\"row\",\"t\":{\"en\":\"Channel\",\"zh-Hans\":\"分发渠道\",\"zh-Hant\":\"分發管道\"},\"v\":{\"en\":\"official\",\"zh-Hans\":\"官方\",\"zh-Hant\":\"官方\"}},{\"k\":\"row\",\"t\":{\"en\":\"Site\",\"zh-Hans\":\"官网\",\"zh-Hant\":\"官網\"}},{\"k\":\"row\",\"t\":{\"en\":\"Source\",\"zh-Hans\":\"源码\",\"zh-Hant\":\"原始碼\"}},{\"k\":\"row\",\"t\":{\"en\":\"Build\",\"zh-Hans\":\"构建指纹\",\"zh-Hant\":\"建置指紋\"},\"v\":{\"en\":\"448ad623 · 2026-09-13\",\"zh-Hans\":\"448ad623 · 2026-09-13\",\"zh-Hant\":\"448ad623 · 2026-09-13\"}},{\"k\":\"body\",\"t\":{\"en\":\"A build whose numbers do not match may have been tampered with. Do not enter any key into it.\",\"zh-Hans\":\"版本号或指纹不一致的版本可能被篡改，不要在其中输入任何密钥。\",\"zh-Hant\":\"版本號或指紋不一致的版本可能被竄改，不要在其中輸入任何金鑰。\"},\"style\":\"danger\"}]}}]}]}"
}
